import type { PatenteHistorico } from './Seccion7_6Patentes';

type FilaEDCA = [
  numero: string,
  fecha: string,
  descripcion: string,
  tieneEfectosGenerales?: string,
  ultimaActualizacion?: string,
  tipoNorma?: string,
  fechaPublicacion?: string,
  enlaceModificacion?: string
];

const crearRegistrosEDCA = (filas: FilaEDCA[]): PatenteHistorico[] =>
  filas.map(([numero, fecha, descripcion, tieneEfectosGenerales, ultimaActualizacion = 'Sin Modificaciones', tipoNorma, fechaPublicacion, enlaceModificacion]) => {
    const mes = fecha.slice(3, 5);
    const anioFecha = fecha.slice(6);
    const anio = anioFecha.length === 2 ? `20${anioFecha}` : anioFecha;
    const dia = Number(fecha.slice(0, 2));
    const fechaPublicacionPorAnio: Record<string, Record<string, string>> = {
      '2015': {
        '01': '06.02.2015, Página Web',
        '02': '06.03.2015, Página Web',
        '03': '06.04.2015, Página Web',
        '04': '06.05.2015, Página Web',
        '05': '06.06.2015, Página Web',
        '06': '06.07.2015, Página Web',
        '07': '06.08.2015, Página Web',
        '08': '06.09.2015, Página Web',
        '09': '07.10.2015, Página Web',
        '10': '06.11.2015, Página Web',
        '11': '05.12.2015, Página Web',
        '12': '06.01.2016, Página Web'
      },
      '2016': {
        '01': '05.02.2016, Página Web',
        '02': '05.03.2016, Página Web',
        '03': '05.04.2016, Página Web',
        '04': '05.05.2016, Página Web',
        '05': '03.06.2016, Página Web',
        '06': '03.06.2016, Página Web'
      },
      '2014': {
        '01': '06.02.2014, Página Web',
        '02': '06.03.2014, Página Web',
        '03': '06.04.2014, Página Web',
        '04': '06.05.2014, Página Web',
        '05': '06.06.2014, Página Web',
        '06': '06.07.2014, Página Web',
        '07': '06.08.2014, Página Web',
        '08': '06.09.2014, Página Web',
        '09': '06.10.2014, Página Web',
        '10': '06.11.2014, Página Web',
        '11': '06.12.2014, Página Web',
        '12': '06.01.2015, Página Web'
      }
    };

    const fechaPublicacion2013 = (): string => {
      if (anio !== '2013') return fechaPublicacionPorAnio[anio]?.[mes] ?? '';
      const fechaOrdenable = `${mes}${fecha.slice(0, 2)}`;
      if (fechaOrdenable <= '0214') return '01.03.2013, Página Web';
      if (fechaOrdenable <= '0308') return '15.03.2013, Página Web';
      if (fechaOrdenable <= '0322') return '05.04.2013, Página Web';
      if (fechaOrdenable <= '0502') return '03.05.2013, Página Web';
      if (fechaOrdenable <= '0614') return '21.06.2013, Página Web';
      if (fechaOrdenable <= '0701') return '02.07.2013, Página Web';
      if (fechaOrdenable <= '0731') return '09.08.2013, Página Web';
      if (fechaOrdenable <= '0820') return '22.08.2013, Página Web';
      if (fechaOrdenable <= '0827') return '06.09.2013, Página Web';
      if (fechaOrdenable <= '0906') return '06.10.2013, Página Web';
      if (fechaOrdenable <= '1020') return '06.11.2013, Página Web';
      if (fechaOrdenable <= '1125') return '06.12.2013, Página Web';
      return '06.01.2014, Página Web';
    };

    return {
      tipoNorma: tipoNorma ?? (anio === '2014' || anio === '2013' || anio === '2012' || anio === '2011' || anio === '2010' || anio === '2009' ? 'Decreto' : 'Decretos Exentos'),
      denominacion: 'Patentes y Permisos',
      nombreTitulo: anio === '2012'
        ? 'Eliminación, Descarga y Caduca'
        : anio === '2011'
          ? 'Elimina, Devuelve, Caduca y anula'
          : 'Elimina, Devuelve, Caduca y anula',
      numero,
      fecha,
      fechaPublicacion: anio === '2012'
        ? 'Página Web, de fecha 29.04.2014'
        : anio === '2009'
          ? fechaPublicacion ?? 'Página Web'
        : anio === '2010'
          ? fechaPublicacion ?? 'Página Web'
        : anio === '2011'
          ? fechaPublicacion ?? 'Página Web'
          : anio === '2014' && mes === '04' && dia >= 7 && dia <= 14
            ? '25.04.2014, Página Web'
            : fechaPublicacion2013(),
      tieneEfectosGenerales: tieneEfectosGenerales ?? (anio === '2014' || (anio === '2013' && (mes > '08' || (mes === '08' && dia >= 26))) ? 'No' : 'Sí'),
      ultimaActualizacion,
      descripcion,
      enlacePublicacion: 'PDF',
      enlaceModificacion: enlaceModificacion ?? (anio === '2012'
        ? 'Sin Enlaces'
        : anio === '2009'
          ? ''
        : anio === '2010'
          ? ''
          : ultimaActualizacion === 'Sin Modificaciones' ? 'Sin Modificaciones' : 'PDF'),
      urlPublicacion: '',
      urlModificacion: ''
    };
  });

